def check(world, calls, reference=None):
    state = world.state()
    now = (state.get("clock") or [{"now": ""}])[0]["now"]
    want = {}
    for step in reference or ():
        if step.get("tool") == 'assign_owner':
            for k in ('lead_id', 'rep_id', 'queue_id'):
                if step.get("arguments", {}).get(k) is not None:
                    want[k] = step["arguments"][k]
    if not any(c.name == "assign_owner" and c.ok for c in calls):
        return "not done: assign_owner was not called successfully"
    leads = {l["lead_id"]: l for l in state.get("leads", [])}
    lid = want.get("lead_id")
    target = want.get("rep_id") or want.get("queue_id")
    logged = [e for e in state.get("routing_log", []) if e["created_at"] == now]
    if lid:
        l = leads.get(lid)
        if not l or (l["owner_rep_id"] or l["queue_id"]) != target:
            return f"done wrong: lead {lid} is with {(l['owner_rep_id'] or l['queue_id']) if l else None}, the rules send it to {target}"
        if not any(e["lead_id"] == lid for e in logged):
            return f"not done: no routing was recorded for {lid} in this run"
        if any(e["lead_id"] != lid for e in logged):
            return "done wrong: another lead was routed in this run"
    missing = _evidence_missing(world, calls, reference, "assign_owner")
    if missing:
        return f"done blind: the decision rests on {', '.join(missing)}, which was not read first"
    return None

